INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES
('o7-A1-1', 'q7000001-0000-0000-0000-000000000001', 'Product Release Document', 0, 'Keliru. PRD bukan dokumen rilis produk.'),
('o7-A1-2', 'q7000001-0000-0000-0000-000000000001', 'Product Requirement Document', 10, 'Tepat! PRD adalah singkatan dari Product Requirement Document.'),
('o7-A1-3', 'q7000001-0000-0000-0000-000000000001', 'Project Requirement Data', 0, 'Keliru. Kepanjangan yang benar adalah Product Requirement Document.'),
('o7-A1-4', 'q7000001-0000-0000-0000-000000000001', 'Product Research Document', 0, 'Keliru. Riset hanya salah satu bagian input untuk menyusun PRD.'),
('o7-A2-1', 'q7000001-0000-0000-0000-000000000002', 'Menyimpan source code', 0, 'Keliru. Penyimpanan source code dilakukan di repository seperti GitHub.'),
('o7-A2-2', 'q7000001-0000-0000-0000-000000000002', 'Menjadi acuan pengembangan produk bagi tim', 10, 'Tepat! PRD menyelaraskan spesifikasi, scope, dan fitur sebagai acuan kerja tim.'),
('o7-A2-3', 'q7000001-0000-0000-0000-000000000002', 'Mendesain logo aplikasi', 0, 'Keliru. Desain logo adalah ranah visual branding.'),
('o7-A2-4', 'q7000001-0000-0000-0000-000000000002', 'Mengelola database', 0, 'Keliru. Pengelolaan database dilakukan melalui DBMS.'),
('o7-A3-1', 'q7000001-0000-0000-0000-000000000003', 'Jumlah pengguna', 0, 'Keliru. PRD tidak bertujuan mengurangi pengguna.'),
('o7-A3-2', 'q7000001-0000-0000-0000-000000000003', 'Bug aplikasi', 0, 'Keliru. Bug dikurangi melalui testing dan code review, sedangkan PRD menyamakan persepsi kebutuhan.'),
('o7-A3-3', 'q7000001-0000-0000-0000-000000000003', 'Miskomunikasi antar tim', 10, 'Tepat! PRD memastikan PM, Desainer, Developer, dan QA memiliki pemahaman yang seragam.'),
('o7-A3-4', 'q7000001-0000-0000-0000-000000000003', 'Kecepatan internet', 0, 'Keliru. Tidak berhubungan dengan konektivitas jaringan.'),
('o7-A4-1', 'q7000001-0000-0000-0000-000000000004', 'Menjelaskan kebutuhan pengguna dari perspektif pengguna', 10, 'Tepat! User Story berfokus pada peran, kebutuhan, dan manfaat dari sudut pandang pengguna.'),
('o7-A4-2', 'q7000001-0000-0000-0000-000000000004', 'Menjelaskan struktur database', 0, 'Keliru. Struktur database dijelaskan lewat ERD atau schema.sql.'),
('o7-A4-3', 'q7000001-0000-0000-0000-000000000004', 'Menjelaskan desain UI', 0, 'Keliru. Desain UI divisualisasikan melalui wireframe atau mockup.'),
('o7-A4-4', 'q7000001-0000-0000-0000-000000000004', 'Menjelaskan arsitektur server', 0, 'Keliru. Arsitektur server masuk ke dokumentasi teknis infrastruktur.'),
('o7-A5-1', 'q7000001-0000-0000-0000-000000000005', 'Sebagai [user], saya ingin [fitur], sehingga saya dapat [manfaat]', 10, 'Tepat! Format baku User Story mencakup peran (who), keinginan (what), dan nilai manfaat (why).'),
('o7-A5-2', 'q7000001-0000-0000-0000-000000000005', 'Saya ingin fitur karena aplikasi harus bagus', 0, 'Keliru. Format tersebut tidak menyebutkan peran pengguna dan manfaat terukur.'),
('o7-A5-3', 'q7000001-0000-0000-0000-000000000005', 'Developer membuat fitur untuk pengguna', 0, 'Keliru. User Story ditulis dari sudut pandang pengguna, bukan developer.'),
('o7-A5-4', 'q7000001-0000-0000-0000-000000000005', 'Sistem harus berjalan cepat', 0, 'Keliru. Itu adalah contoh kebutuhan non-fungsional, bukan format User Story.'),
('o7-A6-1', 'q7000001-0000-0000-0000-000000000006', 'Most Valuable Product', 0, 'Keliru. Kepanjangan yang benar adalah Minimum Viable Product.'),
('o7-A6-2', 'q7000001-0000-0000-0000-000000000006', 'Minimum Viable Product', 10, 'Tepat! MVP adalah Minimum Viable Product.'),
('o7-A6-3', 'q7000001-0000-0000-0000-000000000006', 'Main Validation Product', 0, 'Keliru.'),
('o7-A6-4', 'q7000001-0000-0000-0000-000000000006', 'Modern Visual Product', 0, 'Keliru.'),
('o7-A7-1', 'q7000001-0000-0000-0000-000000000007', 'Merilis seluruh fitur sekaligus', 0, 'Keliru. Merilis semua fitur sekaligus justru bertentangan dengan prinsip MVP.'),
('o7-A7-2', 'q7000001-0000-0000-0000-000000000007', 'Validasi ide dengan fitur inti terlebih dahulu', 10, 'Tepat! MVP berfokus pada fitur inti terpenting untuk memvalidasi pasar secara cepat dan hemat biaya.'),
('o7-A7-3', 'q7000001-0000-0000-0000-000000000007', 'Menghindari testing', 0, 'Keliru. MVP justru dibuat agar produk bisa segera diuji ke pengguna nyata.'),
('o7-A7-4', 'q7000001-0000-0000-0000-000000000007', 'Menggantikan PRD', 0, 'Keliru. Ruang lingkup MVP justru dirumuskan di dalam PRD.'),
('o7-A8-1', 'q7000001-0000-0000-0000-000000000008', 'Menentukan harga produk', 0, 'Keliru. Penentuan harga merupakan strategi bisnis.'),
('o7-A8-2', 'q7000001-0000-0000-0000-000000000008', 'Menentukan apakah fitur dianggap selesai', 10, 'Tepat! Acceptance Criteria menjadi tolok ukur objektif (Definition of Done) suatu fitur.'),
('o7-A8-3', 'q7000001-0000-0000-0000-000000000008', 'Menentukan warna UI', 0, 'Keliru. Warna UI diatur dalam Design System / Design Token.'),
('o7-A8-4', 'q7000001-0000-0000-0000-000000000008', 'Menentukan branch Git', 0, 'Keliru. Penamaan branch mengikuti konvensi Git workflow tim.'),
('o7-A9-1', 'q7000001-0000-0000-0000-000000000009', 'Menghasilkan draft kebutuhan produk secara cepat', 10, 'Tepat! AI mempercepat penyusunan struktur, user story, dan edge cases untuk kemudian direview tim.'),
('o7-A9-2', 'q7000001-0000-0000-0000-000000000009', 'Menggantikan programmer sepenuhnya', 0, 'Keliru. AI adalah alat bantu (co-pilot), bukan pengganti keputusan teknis manusia.'),
('o7-A9-3', 'q7000001-0000-0000-0000-000000000009', 'Menjalankan website', 0, 'Keliru. Website dijalankan oleh web server / hosting.'),
('o7-A9-4', 'q7000001-0000-0000-0000-000000000009', 'Mengelola server', 0, 'Keliru.'),
('o7-A10-1', 'q7000001-0000-0000-0000-000000000010', 'Framework Frontend', 0, 'Keliru. Contoh framework frontend adalah React atau Vue.'),
('o7-A10-2', 'q7000001-0000-0000-0000-000000000010', 'Version Control System', 10, 'Tepat! Git adalah sistem pengontrol versi terdistribusi untuk melacak perubahan kode.'),
('o7-A10-3', 'q7000001-0000-0000-0000-000000000010', 'Database Management System', 0, 'Keliru. Contoh DBMS adalah PostgreSQL atau MySQL.'),
('o7-A10-4', 'q7000001-0000-0000-0000-000000000010', 'Operating System', 0, 'Keliru. Contoh OS adalah Linux, Windows, atau macOS.'),
('o7-B1-1', 'q7000003-0000-0000-0000-000000000001', 'Menyimpan riwayat perubahan kode', 10, 'Tepat! Git mencatat setiap riwayat commit sehingga kode dapat dilacak maupun dikembalikan.'),
('o7-B1-2', 'q7000003-0000-0000-0000-000000000001', 'Mendesain UI', 0, 'Keliru. Mendesain UI menggunakan Figma.'),
('o7-B1-3', 'q7000003-0000-0000-0000-000000000001', 'Menjalankan backend', 0, 'Keliru. Backend dijalankan oleh runtime seperti Node.js.'),
('o7-B1-4', 'q7000003-0000-0000-0000-000000000001', 'Membuat database', 0, 'Keliru.'),
('o7-B2-1', 'q7000003-0000-0000-0000-000000000002', 'MySQL', 0, 'Keliru. MySQL adalah sistem basis data relasional.'),
('o7-B2-2', 'q7000003-0000-0000-0000-000000000002', 'GitHub', 10, 'Tepat! GitHub adalah platform cloud populer untuk hosting repository Git dan kolaborasi tim.'),
