('o7-B3-1', 'q7000003-0000-0000-0000-000000000003', 'Tempat menyimpan proyek dan riwayatnya', 10, 'Tepat! Repository menyimpan seluruh file proyek beserta log revisi perubahannya.'),
('o7-B3-2', 'q7000003-0000-0000-0000-000000000003', 'Tempat menyimpan desain Figma', 0, 'Keliru. File desain Figma disimpan di cloud Figma.'),
('o7-B3-3', 'q7000003-0000-0000-0000-000000000003', 'Tempat menyimpan database cloud', 0, 'Keliru. Database cloud dikelola oleh layanan seperti Supabase.'),
