('o7-B5-1', 'q7000003-0000-0000-0000-000000000005', 'Membuat jalur pengembangan terpisah', 10, 'Tepat! Branch mengisolasi pengerjaan fitur atau perbaikan bug tanpa mengganggu branch utama.'),
('o7-B5-2', 'q7000003-0000-0000-0000-000000000005', 'Membuat database baru', 0, 'Keliru.'),
