('o7-B6-1', 'q7000003-0000-0000-0000-000000000006', 'Menghindari modifikasi langsung pada kode utama', 10, 'Tepat! Kode di branch main/production tetap stabil sementara fitur baru dikerjakan di branch terpisah.'),
('o7-B6-2', 'q7000003-0000-0000-0000-000000000006', 'Membuat internet lebih cepat', 0, 'Keliru.'),
('o7-B6-3', 'q7000003-0000-0000-0000-000000000006', 'Menghilangkan bug otomatis', 0, 'Keliru. Bug tetap harus diperbaiki oleh developer.'),
