('o7-C3-1', 'q7000005-0000-0000-0000-000000000003', 'Selalu digunakan', 0, 'Keliru. Penggunaan --force secara sembarangan sangat berbahaya pada repo bersama.'),
('o7-C3-2', 'q7000005-0000-0000-0000-000000000003', 'Dihindari karena dapat menimpa pekerjaan anggota lain', 10, 'Tepat! git push --force menulis ulang riwayat commit remote sehingga berisiko menghapus kerja tim.'),
('o7-C3-3', 'q7000005-0000-0000-0000-000000000003', 'Digunakan setiap hari', 0, 'Keliru.'),
('o7-C3-4', 'q7000005-0000-0000-0000-000000000003', 'Wajib dilakukan sebelum merge', 0, 'Keliru.'),
('o7-C4-1', 'q7000005-0000-0000-0000-000000000004', 'Membagi database menjadi beberapa tabel', 0, 'Keliru. Itu disebut normalisasi atau partisi tabel database.'),
('o7-C4-2', 'q7000005-0000-0000-0000-000000000004', 'Mengubah desain menjadi kode frontend', 10, 'Tepat! Slicing Design menerjemahkan mockup UI (misal dari Figma) ke HTML, CSS, dan komponen frontend.'),
('o7-C4-3', 'q7000005-0000-0000-0000-000000000004', 'Menghapus komponen desain', 0, 'Keliru.'),
('o7-C4-4', 'q7000005-0000-0000-0000-000000000004', 'Menambahkan animasi', 0, 'Keliru. Animasi hanyalah salah satu detail interaktif, bukan definisi slicing.'),
('o7-C5-1', 'q7000005-0000-0000-0000-000000000005', 'MySQL', 0, 'Keliru. MySQL adalah database.'),
('o7-C5-2', 'q7000005-0000-0000-0000-000000000005', 'Figma', 10, 'Tepat! Figma menyediakan fitur inspect properti CSS, ukuran, warna, dan ekspor aset untuk slicing.'),
('o7-C5-3', 'q7000005-0000-0000-0000-000000000005', 'PostgreSQL', 0, 'Keliru. PostgreSQL adalah database.'),
('o7-C5-4', 'q7000005-0000-0000-0000-000000000005', 'MongoDB', 0, 'Keliru. MongoDB adalah database NoSQL.'),
('o7-C6-1', 'q7000005-0000-0000-0000-000000000006', 'Membuat struktur kode lebih bermakna dan mudah dipahami', 10, 'Tepat! Tag semantik meningkatkan keterbacaan kode, aksesibilitas screen reader, dan SEO.'),
('o7-C6-2', 'q7000005-0000-0000-0000-000000000006', 'Memperbesar ukuran file', 0, 'Keliru.'),
('o7-C6-3', 'q7000005-0000-0000-0000-000000000006', 'Mengurangi jumlah halaman', 0, 'Keliru.'),
('o7-C6-4', 'q7000005-0000-0000-0000-000000000006', 'Menggantikan CSS', 0, 'Keliru. CSS tetap diperlukan untuk mengatur tata letak dan tampilan visual.'),
('o7-C7-1', 'q7000005-0000-0000-0000-000000000007', 'Konsistensi warna, font, dan spacing', 10, 'Tepat! Design Token menyimpan nilai desain dalam variabel terpusat agar UI konsisten.'),
('o7-C7-2', 'q7000005-0000-0000-0000-000000000007', 'Ukuran database', 0, 'Keliru.'),
('o7-C7-3', 'q7000005-0000-0000-0000-000000000007', 'Kecepatan server', 0, 'Keliru.'),
('o7-C7-4', 'q7000005-0000-0000-0000-000000000007', 'Jumlah pengguna', 0, 'Keliru.'),
('o7-C8-1', 'q7000005-0000-0000-0000-000000000008', 'Mendesain untuk mobile terlebih dahulu sebelum desktop', 10, 'Tepat! Mobile-First memprioritaskan layar kecil terlebih dahulu lalu memperluas layout ke tablet dan desktop.'),
('o7-C8-2', 'q7000005-0000-0000-0000-000000000008', 'Hanya mendukung Android', 0, 'Keliru. Mobile-First berlaku lintas perangkat.'),
('o7-C8-3', 'q7000005-0000-0000-0000-000000000008', 'Mengabaikan desktop', 0, 'Keliru. Tampilan desktop tetap dioptimalkan melalui media query / breakpoint.'),
('o7-C8-4', 'q7000005-0000-0000-0000-000000000008', 'Membuat aplikasi mobile saja', 0, 'Keliru.'),
('o7-C9-1', 'q7000005-0000-0000-0000-000000000009', 'Memecah aplikasi menjadi bagian-bagian yang mudah dikelola', 10, 'Tepat! Modular development memecah kode menjadi komponen kecil yang reusable dan mudah dirawat.'),
('o7-C9-2', 'q7000005-0000-0000-0000-000000000009', 'Membuat kode lebih panjang', 0, 'Keliru.'),
('o7-C9-3', 'q7000005-0000-0000-0000-000000000009', 'Mengurangi jumlah fitur', 0, 'Keliru.'),
('o7-C9-4', 'q7000005-0000-0000-0000-000000000009', 'Menghapus komponen UI', 0, 'Keliru.'),
('o7-C10-1', 'q7000005-0000-0000-0000-000000000010', 'Logo dan poster aplikasi', 0, 'Keliru.'),
('o7-C10-2', 'q7000005-0000-0000-0000-000000000010', 'PRD, Repository GitHub Kolaboratif, dan Prototype Responsif', 10, 'Tepat! Output lengkap Modul 7 mencakup dokumen PRD, alur kolaborasi GitHub, dan hasil slicing responsif.'),
('o7-C10-3', 'q7000005-0000-0000-0000-000000000010', 'Database dan hosting', 0, 'Keliru. Integrasi database dan deploy dibahas pada Modul 8.'),
('o7-C10-4', 'q7000005-0000-0000-0000-000000000010', 'Landing page saja', 0, 'Keliru. Terlalu sempit dan tidak mencakup aspek PRD serta kolaborasi Git.');
INSERT INTO essay_rubrics (id, question_id, kunci_jawaban, kata_kunci, rubrik_skor) VALUES
('er-7000001-0000-0000-0000-000000000001', 'q7000002-0000-0000-0000-000000000001', 'PRD adalah dokumen yang menjelaskan kebutuhan, tujuan, fitur, ruang lingkup, dan spesifikasi suatu produk sehingga seluruh tim memiliki pemahaman yang sama dalam proses pengembangan.', ARRAY['prd', 'kebutuhan produk', 'fitur', 'ruang lingkup', 'spesifikasi', 'acuan tim']::text[], '{"0":"Tidak relevan","7":"PRD adalah dokumen proyek (terlalu umum)","8":"PRD adalah dokumen perencanaan produk (belum menjelaskan fungsi acuan bersama tim dan ruang lingkup)","9":"PRD adalah dokumen yang menjelaskan kebutuhan dan fitur produk","10":"Menjelaskan definisi PRD beserta kebutuhan, fitur, ruang lingkup, dan fungsinya sebagai acuan tim"}'::jsonb),
('er-7000001-0000-0000-0000-000000000002', 'q7000002-0000-0000-0000-000000000002', 'PRD penting karena menyelaraskan pemahaman seluruh tim, mengurangi miskomunikasi, menjadi acuan pengembangan, dan membantu memastikan produk dibangun sesuai kebutuhan pengguna dan bisnis.', ARRAY['acuan tim', 'komunikasi', 'miskomunikasi', 'kebutuhan pengguna', 'pengembangan produk', 'sinkronisasi tim']::text[], '{"0":"Tidak relevan","7":"PRD digunakan sebelum coding (hanya menjelaskan urutan proses)","8":"PRD membantu proses pengembangan (belum menjelaskan komunikasi tim)","9":"PRD membantu tim memiliki tujuan yang sama","10":"Menjelaskan penyelarasan tim, pengurangan miskomunikasi, dan acuan kebutuhan pengguna/bisnis"}'::jsonb),
('er-7000001-0000-0000-0000-000000000003', 'q7000002-0000-0000-0000-000000000003', 'User Story adalah deskripsi kebutuhan pengguna dari sudut pandang pengguna yang menjelaskan apa yang ingin dicapai dan manfaat yang diperoleh.', ARRAY['user story', 'kebutuhan pengguna', 'perspektif pengguna', 'sudut pandang pengguna', 'manfaat']::text[], '{"0":"Tidak relevan","7":"Hanya menyebut ide umum tanpa kedalaman konsep","8":"Sekitar 60% konsep benar dan penjelasan masih umum","9":"Konsep inti benar namun 1 unsur penjelas belum disebutkan","10":"Menjelaskan deskripsi kebutuhan dari perspektif pengguna beserta tujuan dan manfaatnya"}'::jsonb),
('er-7000001-0000-0000-0000-000000000004', 'q7000002-0000-0000-0000-000000000004', 'Sebagai [jenis pengguna], saya ingin [fitur/kebutuhan], sehingga saya dapat [manfaat/tujuan].', ARRAY['sebagai pengguna', 'saya ingin', 'sehingga saya dapat']::text[], '{"0":"Tidak relevan","7":"Hanya menjelaskan pengertian umum User Story tanpa format","8":"Menuliskan sebagian struktur User Story","9":"Format inti benar namun kurang 1 bagian penjelas","10":"Menuliskan format lengkap User Story (Sebagai pengguna, saya ingin fitur, sehingga saya dapat manfaat)"}'::jsonb),
('er-7000001-0000-0000-0000-000000000005', 'q7000002-0000-0000-0000-000000000005', 'MVP adalah versi awal produk yang hanya memiliki fitur inti yang cukup untuk memberikan nilai kepada pengguna dan memperoleh validasi pasar.', ARRAY['mvp', 'fitur inti', 'validasi', 'pengguna', 'pasar']::text[], '{"0":"Tidak relevan","7":"MVP adalah produk pertama (tidak menjelaskan fokus fitur inti)","8":"MVP adalah produk sederhana (belum menjelaskan tujuan validasi)","9":"MVP adalah produk awal dengan fitur penting saja","10":"Menjelaskan versi awal produk dengan fitur inti untuk memberikan nilai dan validasi pasar"}'::jsonb),
('er-7000001-0000-0000-0000-000000000006', 'q7000004-0000-0000-0000-000000000001', 'Acceptance Criteria adalah kondisi atau standar yang harus terpenuhi agar suatu fitur dianggap selesai dan sesuai kebutuhan.', ARRAY['acceptance criteria', 'standar', 'kondisi', 'fitur selesai', 'validasi']::text[], '{"0":"Tidak relevan","7":"Ide umum tanpa kedalaman konsep","8":"Penjelasan masih umum tentang syarat fitur","9":"Konsep inti benar namun kurang 1 unsur penting","10":"Menjelaskan standar atau kondisi yang wajib terpenuhi agar fitur dianggap selesai dan valid"}'::jsonb),
('er-7000001-0000-0000-0000-000000000007', 'q7000004-0000-0000-0000-000000000002', 'Git adalah sistem version control yang digunakan untuk melacak perubahan kode, mendukung kolaborasi tim, dan mengelola riwayat pengembangan proyek.', ARRAY['git', 'version control', 'riwayat perubahan', 'melacak perubahan', 'kolaborasi']::text[], '{"0":"Tidak relevan","7":"Ide umum tanpa kedalaman konsep","8":"Penjelasan umum tentang penyimpanan kode di Git","9":"Konsep inti benar namun kurang 1 unsur penting","10":"Menjelaskan Git sebagai version control untuk melacak riwayat perubahan dan mendukung kolaborasi tim"}'::jsonb),
('er-7000001-0000-0000-0000-000000000008', 'q7000004-0000-0000-0000-000000000003', 'GitHub mempermudah penyimpanan kode, kolaborasi tim, code review, pengelolaan branch, dan integrasi pengembangan secara terpusat.', ARRAY['github', 'repository', 'kolaborasi', 'code review', 'branch']::text[], '{"0":"Tidak relevan","7":"Ide umum tanpa kedalaman konsep","8":"Penjelasan umum tentang kerja sama tim di GitHub","9":"Konsep inti benar namun kurang 1 unsur penting","10":"Menjelaskan penyimpanan repository terpusat, kolaborasi tim, code review, dan pengelolaan branch"}'::jsonb),
('er-7000001-0000-0000-0000-000000000009', 'q7000004-0000-0000-0000-000000000004', 'Repository adalah tempat penyimpanan seluruh proyek beserta riwayatnya, sedangkan Branch adalah cabang kerja terpisah yang digunakan untuk mengembangkan fitur atau perubahan tertentu.', ARRAY['repository', 'branch', 'penyimpanan proyek', 'cabang kerja', 'terpisah']::text[], '{"0":"Tidak relevan","7":"Ide umum tanpa kedalaman konsep","8":"Menjelaskan definisi umum tanpa perbandingan yang tajam","9":"Konsep inti benar namun kurang 1 unsur penting","10":"Membedakan repository (penyimpanan seluruh proyek & riwayat) dengan branch (cabang kerja terpisah)"}'::jsonb),
('er-7000001-0000-0000-0000-000000000010', 'q7000004-0000-0000-0000-000000000005', 'Pull Request digunakan untuk meminta peninjauan (review) dan penggabungan perubahan kode dari suatu branch ke branch lain.', ARRAY['pull request', 'review', 'peninjauan', 'merge', 'penggabungan', 'branch']::text[], '{"0":"Tidak relevan","7":"Ide umum tanpa kedalaman konsep","8":"Penjelasan umum tentang menggabungkan branch","9":"Konsep inti benar namun kurang 1 unsur penting","10":"Menjelaskan fungsi PR untuk meminta review dan penggabungan (merge) perubahan antar branch"}'::jsonb),
('er-7000001-0000-0000-0000-000000000011', 'q7000006-0000-0000-0000-000000000001', 'Code Review membantu meningkatkan kualitas kode, menemukan bug lebih awal, menjaga konsistensi standar coding, dan mendukung pembelajaran antar anggota tim.', ARRAY['code review', 'kualitas kode', 'bug', 'standar coding', 'kolaborasi']::text[], '{"0":"Tidak relevan","7":"Ide umum tanpa kedalaman konsep","8":"Penjelasan umum tentang memeriksa kode rekan","9":"Konsep inti benar namun kurang 1 unsur penting","10":"Menjelaskan peningkatan kualitas kode, deteksi bug lebih awal, dan konsistensi standar coding tim"}'::jsonb),
('er-7000001-0000-0000-0000-000000000012', 'q7000006-0000-0000-0000-000000000002', 'Merge Conflict terjadi ketika Git tidak dapat menggabungkan perubahan secara otomatis karena terdapat perubahan yang saling bertabrakan pada bagian kode yang sama.', ARRAY['merge conflict', 'konflik perubahan', 'kode bertabrakan', 'git', 'bagian kode yang sama']::text[], '{"0":"Tidak relevan","7":"Merge Conflict terjadi di Git (tidak menjelaskan definisinya)","8":"Merge Conflict adalah error saat merge (belum menjelaskan penyebab konflik perubahan kode)","9":"Merge Conflict terjadi ketika dua perubahan tidak bisa digabung otomatis","10":"Menjelaskan Git gagal merge otomatis karena ada perubahan bertabrakan pada bagian kode yang sama"}'::jsonb),
('er-7000001-0000-0000-0000-000000000013', 'q7000006-0000-0000-0000-000000000003', 'Slicing Design adalah proses menerjemahkan desain UI dari tools seperti Figma menjadi kode frontend yang dapat dijalankan pada aplikasi atau website.', ARRAY['slicing design', 'figma', 'frontend', 'implementasi kode', 'desain ui']::text[], '{"0":"Tidak relevan","7":"Ide umum tanpa kedalaman konsep","8":"Penjelasan umum mengubah desain menjadi tampilan web","9":"Konsep inti benar namun kurang 1 unsur penting","10":"Menjelaskan proses menerjemahkan desain UI (seperti Figma) menjadi kode frontend web/aplikasi"}'::jsonb),
('er-7000001-0000-0000-0000-000000000014', 'q7000006-0000-0000-0000-000000000004', 'Design Token menjaga konsistensi warna, tipografi, spacing, dan elemen visual lainnya sehingga desain lebih mudah dikelola dan diimplementasikan.', ARRAY['design token', 'konsistensi', 'warna', 'typography', 'tipografi', 'spacing']::text[], '{"0":"Tidak relevan","7":"Design Token berkaitan dengan UI (terlalu umum)","8":"Design Token digunakan dalam desain (belum menjelaskan aspek konsistensi dan implementasi teknis)","9":"Design Token membantu menjaga konsistensi desain","10":"Menjelaskan Design Token menjaga konsistensi warna, tipografi, dan spacing dalam implementasi frontend"}'::jsonb),
('er-7000001-0000-0000-0000-000000000015', 'q7000006-0000-0000-0000-000000000005', 'Mobile-First adalah pendekatan desain dan pengembangan yang memulai perancangan dari layar perangkat mobile terlebih dahulu sebelum dikembangkan ke ukuran layar yang lebih besar.', ARRAY['mobile-first', 'mobile', 'responsive', 'layar kecil', 'pengembangan bertahap', 'layar yang lebih besar']::text[], '{"0":"Tidak relevan","7":"Website bisa dibuka di HP (tidak menjelaskan konsep Mobile-First)","8":"Mobile-First berarti mendukung tampilan mobile (belum menjelaskan urutan pengembangan)","9":"Desain dibuat untuk mobile terlebih dahulu sebelum desktop","10":"Menjelaskan perancangan dimulai dari layar mobile terlebih dahulu sebelum ke layar yang lebih besar"}'::jsonb);
